class Solution {public int[][]solve(int[] next){int n=next.length;int[] degree=new int[n],length=new int[n],distance=new int[n];for(int v:next)degree[v]++;ArrayList<Integer>order=new ArrayList<>();for(int u=0;u<n;u++)if(degree[u]==0)order.add(u);for(int i=0;i<order.size();i++)if(--degree[next[order.get(i)]]==0)order.add(next[order.get(i)]);for(int u=0;u<n;u++)if(degree[u]>0&&length[u]==0){ArrayList<Integer>cycle=new ArrayList<>();cycle.add(u);for(int v=next[u];v!=u;v=next[v])cycle.add(v);for(int v:cycle)length[v]=cycle.size();}for(int i=order.size()-1;i>=0;i--){int u=order.get(i);length[u]=length[next[u]];distance[u]=distance[next[u]]+1;}int[][]out=new int[n][2];for(int i=0;i<n;i++){out[i][0]=length[i];out[i][1]=distance[i];}return out;}}